private void testFailWithPosition(String message, String json) throws IOException {
  // Validate that it works reading the string normally.
  JsonReader reader1 = newReader(json);
  reader1.setLenient(true);
  reader1.beginArray();
  reader1.nextString();
  try {
    reader1.peek();
    fail();
  } catch (JsonEncodingException expected) {
    assertThat(expected).hasMessageThat().isEqualTo(message);
  }

  // Also validate that it works when skipping.
  JsonReader reader2 = newReader(json);
  reader2.setLenient(true);
  reader2.beginArray();
  reader2.skipValue();
  try {
    reader2.peek();
    fail();
  } catch (JsonEncodingException expected) {
    assertThat(expected).hasMessageThat().isEqualTo(message);
  }
}

