   map.put("String", "value");

   String asJson = "{\"boolean\":true,\"float\":42.0,\"String\":\"value\"}";

   Buffer buffer = new Buffer();
   JsonWriter jsonWriter = JsonWriter.of(buffer);
   jsonAdapter.toJson(jsonWriter, map);
